using System.IO.Compression;
using System.Runtime.InteropServices;
using System.Text.Json;
using System.Text.Json.Nodes;
using TextText.Core;

static class FolderCaseTests
{
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool MoveFileW(string source,string destination);
    static void Hook(TextPackStore store,Action<string>? action)=>typeof(TextPackStore).GetProperty("FolderCaseObservationForTesting",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.SetValue(store,action);
    static byte[] Pack(){using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true))using(var writer=new StreamWriter(zip.CreateEntry("text.md").Open()))writer.Write("---\ntextTextId: test-1\n---\nfolder pending exact bytes");return output.ToArray();}
    static TextPackStore Owned(string temp,string name){var store=new TextPackStore(Path.Combine(temp,"folder-case-"+name),Path.Combine(temp,"folder-case-"+name+"-state"));AccountRootOwnership.Open(store,new Uri("https://texttext.test"),"folder-workspace","folder-account");return store;}
    static bool ExactFolder(TextPackStore store,string leaf)=>Directory.EnumerateDirectories(store.Root).Any(path=>Path.GetFileName(path)==leaf);
    static void ExternalRename(TextPackStore store){if(OperatingSystem.IsWindows()){if(!MoveFileW(store.Resolve("Notes"),store.Resolve("notes")))throw new IOException("Fixture native directory rename failed: "+Marshal.GetLastWin32Error());}else Directory.Move(store.Resolve("Notes"),store.Resolve("notes"));}
    static (TextPackStore Store,PackFile File,SharedCheckpoint Checkpoint,byte[] Bytes) Shared(string temp,string name){var store=Owned(temp,name);var bytes=Pack();var file=store.Write("Notes/CaseProbe.textpack",bytes);var directory=Path.Combine(store.StateDirectory,"shared-editing",file.ItemId);Directory.CreateDirectory(directory);var journal=JsonSerializer.Serialize(new{version=1,epoch=3,seq=11,journalGeneration=7,revision=file.Hash,relativePath=file.Path,update="AAA=",pending=new[]{"AAA="},batch=new{operationId="retained-folder-operation",updates=new[]{"AAA="}}});var cp=new SharedCheckpoint(file.ItemId,file.Path,file.Hash,file.Hash,3,11,7,journal,true);File.WriteAllBytes(Path.Combine(directory,"checkpoint.json"),JsonSerializer.SerializeToUtf8Bytes(cp));return(store,file,cp,bytes);}
    static TextPackStore Conflict(string temp,string name){var store=Owned(temp,name);store.EnsureFolders(["Notes"]);File.WriteAllText(store.Resolve("Notes/original.txt"),"retained original");Hook(store,point=>{if(point=="prepared")throw new IOException("Injected pending folder operation");});try{store.EnsureFolders(["notes"]);}catch(IOException){}Hook(store,null);Directory.Move(store.Resolve("Notes"),store.Resolve("retained-original"));Directory.CreateDirectory(store.Resolve("Notes"));File.WriteAllText(store.Resolve("Notes/foreign.txt"),"retained foreign");try{_=store.Scan();}catch(IOException){}return store;}
    public static async Task Run(string temp,Action<bool,string> check){
        {
            var store=Owned(temp,"portable-floor");RetainedReplacementProfile.Prepare(store);var directory=Path.Combine(store.StateDirectory,"retained-replacement-profile");var before=File.ReadAllBytes(Path.Combine(directory,"profile.json"));typeof(RetainedReplacementProfile).GetMethod("PrepareFolderCase",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!.Invoke(null,[store,null]);var marker=JsonSerializer.Deserialize<RetainedReplacementProfile.Marker>(File.ReadAllBytes(Path.Combine(directory,"profile.json")))!;
            check(marker.Version==2&&File.ReadAllBytes(Path.Combine(directory,"profile-v1.json")).SequenceEqual(before)&&File.ReadAllBytes(Path.Combine(directory,"profile-v1-displaced.json")).SequenceEqual(before),"folder compatibility floor retains exact prior profile and rejects known strict version-one format");
            AccountRootOwnership.Open(new TextPackStore(store.Root,store.StateDirectory),new Uri("https://texttext.test"),"folder-workspace","folder-account");check(true,"folder compatibility floor supports new same-principal account factory without changing owner");
            var changed=JsonSerializer.Deserialize<RetainedReplacementProfile.Marker>(before)! with{PrincipalHash=new string('b',64)};File.WriteAllBytes(Path.Combine(directory,"profile-v1-displaced.json"),JsonSerializer.SerializeToUtf8Bytes(changed));var refused=false;try{_=store.Scan();}catch(InvalidDataException){refused=true;}check(refused,"late retained profile changes fence already-open empty workspace inventory");
        }
        if(!OperatingSystem.IsWindows()){Console.WriteLine("SKIP Windows pinned directory mutation fixtures: actual Windows required");return;}
        var probe=Owned(temp,"probe");probe.EnsureFolders(["Notes"]);if(!Directory.Exists(probe.Resolve("notes"))){Console.WriteLine("SKIP folder case fixtures: filesystem aliases unavailable");return;}
        var failures=new List<string>();
        async Task Scenario(string name,Func<Task> body){try{await body();check(true,name);}catch(Exception error){failures.Add(name+": "+error.Message);Console.WriteLine("FAIL "+name+": "+error.Message);}}
        await Scenario("owned empty catalog changes exact folder spelling",()=>{var store=Owned(temp,"empty");store.EnsureFolders(["Notes"]);store.EnsureFolders(["notes"]);if(!ExactFolder(store,"notes")||ExactFolder(store,"Notes"))throw new Exception("requested physical spelling not materialized");return Task.CompletedTask;});
        await Scenario("catalog case alias pruning never deletes the desired empty folder",async()=>{var store=Owned(temp,"catalog");var remote=new Test.Fake{Folders=["Notes"],AuthoritativeFolders=["Notes"]};await Test.NewSync(store,remote).SyncAsync();remote.Folders=["notes"];remote.AuthoritativeFolders=["notes"];await Test.NewSync(store,remote).SyncAsync();if(!ExactFolder(store,"notes")||ExactFolder(store,"Notes"))throw new Exception("authoritative empty alias missing or wrong spelling after pruning");await Test.NewSync(store,remote).SyncAsync();if(!ExactFolder(store,"notes"))throw new Exception("restart deleted desired alias");});
        await Scenario("contradictory same-inode catalog spelling refuses before mutation",()=>{var store=Owned(temp,"contradiction");store.EnsureFolders(["Notes"]);var refused=false;try{store.EnsureFolders(["Notes","notes"]);}catch(IOException){refused=true;}catch(InvalidDataException){refused=true;}if(!refused||!ExactFolder(store,"Notes")||ExactFolder(store,"notes"))throw new Exception("contradictory catalog accepted or existing spelling changed");return Task.CompletedTask;});
        foreach(var active in new[]{false,true})await Scenario("shared pending folder spelling follows all path components active="+active,async()=>{var f=Shared(temp,"shared-"+active);using var editing=new SharedEditingStore(f.Store,Test.NewSync(f.Store,new Test.Fake()));SharedSession? opened=null;
            if(active)opened=await editing.OpenAsync(f.File.ItemId,f.File.Path,f.File.Hash);ExternalRename(f.Store);var target="notes/CaseProbe.textpack";
            if(active){var result=await editing.CheckpointAsync(opened!.SessionToken,f.File.Hash,f.Bytes,f.Checkpoint);if(result.Path!=target)throw new Exception("active checkpoint retained stale parent spelling");}
            else {opened=await editing.OpenAsync(f.File.ItemId,f.File.Path,f.File.Hash);if(opened.Document.Path!=target)throw new Exception("reopened checkpoint retained stale parent spelling");}
            var cp=JsonSerializer.Deserialize<SharedCheckpoint>(File.ReadAllBytes(Path.Combine(f.Store.StateDirectory,"shared-editing",f.File.ItemId,"checkpoint.json")))!;var expected=JsonNode.Parse(f.Checkpoint.Journal)!;expected["relativePath"]=target;if(cp.Path!=target||cp.Epoch!=f.Checkpoint.Epoch||cp.Seq!=f.Checkpoint.Seq||cp.JournalGeneration!=f.Checkpoint.JournalGeneration||!JsonNode.DeepEquals(expected,JsonNode.Parse(cp.Journal)))throw new Exception("folder adoption changed retained journal or identity generation");if(!f.Store.Read(target).SequenceEqual(f.Bytes))throw new Exception("folder adoption changed pack bytes");});
        await Scenario("file rename adopts already exact actual destination after parent spelling change",()=>{var store=Owned(temp,"file-adoption");var bytes=Pack();var file=store.Write("Notes/CaseProbe.textpack",bytes);ExternalRename(store);store.Rename(file.Path,"notes/CaseProbe.textpack",file.Hash);if(!ExactFolder(store,"notes")||!store.Read("notes/CaseProbe.textpack").SequenceEqual(bytes))throw new Exception("semantic adoption changed actual file");return Task.CompletedTask;});

        await Scenario("folder source and parents stay pinned across final mutation hook",()=>{var store=Owned(temp,"pin");store.EnsureFolders(["Notes"]);File.WriteAllText(store.Resolve("Notes/child.txt"),"exact child");var sourceBlocked=false;var parentBlocked=false;Hook(store,point=>{if(point!="beforeRename")return;try{Directory.Move(store.Resolve("Notes"),store.Resolve("unexpected"));}catch(IOException){sourceBlocked=true;}try{Directory.Move(store.Root,store.Root+"-moved");}catch(IOException){parentBlocked=true;}});store.EnsureFolders(["notes"]);if(!sourceBlocked||!parentBlocked||File.ReadAllText(store.Resolve("notes/child.txt"))!="exact child"||!ExactFolder(store,"notes"))throw new Exception("source/parent final-gap pin failed");return Task.CompletedTask;});
        foreach(var boundary in new[]{"prepared","renamed"})await Scenario("folder pending restart classifies native boundary "+boundary,()=>{var store=Owned(temp,"restart-"+boundary);store.EnsureFolders(["Notes"]);File.WriteAllText(store.Resolve("Notes/child.txt"),"restart exact");Hook(store,point=>{if(point==boundary)throw new IOException("Injected folder crash");});try{store.EnsureFolders(["notes"]);}catch(IOException){}var reopened=new TextPackStore(store.Root,store.StateDirectory);_=reopened.Scan();if(boundary=="prepared"&&!ExactFolder(store,"Notes")||boundary=="renamed"&&!ExactFolder(store,"notes"))throw new Exception("restart changed the actual observed folder state");reopened.EnsureFolders(["notes"]);if(!ExactFolder(reopened,"notes")||File.ReadAllText(reopened.Resolve("notes/child.txt"))!="restart exact")throw new Exception("restart failed safe retry");return Task.CompletedTask;});
        await Scenario("folder conflict metadata consent preserves both trees and permits later legitimate rename",()=>{var store=Owned(temp,"resolution");store.EnsureFolders(["Notes"]);File.WriteAllText(store.Resolve("Notes/child.txt"),"original bytes");Hook(store,point=>{if(point=="prepared")throw new IOException("Injected before rename");});try{store.EnsureFolders(["notes"]);}catch(IOException){}Directory.Move(store.Resolve("Notes"),store.Resolve("moved-original"));Directory.CreateDirectory(store.Resolve("Notes"));File.WriteAllText(store.Resolve("Notes/foreign.txt"),"foreign bytes");var fenced=false;try{_=store.Scan();}catch(IOException){fenced=true;}if(!fenced)throw new Exception("conflicting directory identities were not fenced");var row=store.FolderRenameRecoveryList().Single();if(row.Resolved||!row.From.Present||row.To.Present||row.ResolutionBlocked is not null)throw new Exception("metadata inspection does not describe exact endpoints");var stale=false;File.WriteAllText(store.Resolve("Notes/foreign.txt"),"changed foreign bytes");try{store.ResolveFolderRename(row.Id,row.FromPath,row.ToPath,row.Inspection);}catch(IOException){stale=true;}if(!stale)throw new Exception("stale tree inspection accepted");row=store.FolderRenameRecoveryRead(row.Id);var cancelled=false;try{store.ResolveFolderRename(row.Id,row.FromPath,row.ToPath,row.Inspection,()=>throw new OperationCanceledException());}catch(OperationCanceledException){cancelled=true;}if(!cancelled||store.FolderRenameRecoveryRead(row.Id).Resolved)throw new Exception("cancelled consent acknowledged folder state");store.ResolveFolderRename(row.Id,row.FromPath,row.ToPath,row.Inspection);if(!store.FolderRenameRecoveryRead(row.Id).Resolved||File.ReadAllText(store.Resolve("moved-original/child.txt"))!="original bytes"||File.ReadAllText(store.Resolve("Notes/foreign.txt"))!="changed foreign bytes")throw new Exception("metadata consent mutated trees");Hook(store,null);store.EnsureFolders(["notes"]);_=store.Scan();if(!ExactFolder(store,"notes")||!store.FolderRenameRecoveryRead(row.Id).Resolved)throw new Exception("later legitimate folder case change reopened prior consent");return Task.CompletedTask;});
        await Scenario("unowned folder alias refuses before journal or physical mutation",()=>{var store=new TextPackStore(Path.Combine(temp,"folder-case-unowned"),Path.Combine(temp,"folder-case-unowned-state"));store.EnsureFolders(["Notes"]);var refused=false;try{store.EnsureFolders(["notes"]);}catch(LegacyAccountStateException){refused=true;}if(!refused||!ExactFolder(store,"Notes")||Directory.Exists(Path.Combine(store.StateDirectory,"folder-case"))||File.Exists(Path.Combine(store.StateDirectory,AccountRootOwnership.FileName)))throw new Exception("unowned mutation fabricated principal or changed folder");return Task.CompletedTask;});
        foreach(var phase in new[]{"folderProfilePreserved","folderProfileStaged","folderProfilePublished"})await Scenario("folder compatibility floor survives interruption "+phase,()=>{var store=Owned(temp,"floor-"+phase);store.EnsureFolders(["Notes"]);RetainedReplacementProfile.Prepare(store);var profile=Path.Combine(store.StateDirectory,"retained-replacement-profile","profile.json");var original=File.ReadAllBytes(profile);Hook(store,point=>{if(point==phase)throw new IOException("Injected profile interruption");});try{store.EnsureFolders(["notes"]);}catch(IOException){}if(!ExactFolder(store,"Notes"))throw new Exception("OS mutation preceded compatibility floor");Hook(store,null);store.EnsureFolders(["notes"]);var marker=JsonSerializer.Deserialize<RetainedReplacementProfile.Marker>(File.ReadAllBytes(profile))!;if(marker.Version!=2||!File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(profile)!,"profile-v1.json")).SequenceEqual(original)||!File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(profile)!,"profile-v1-displaced.json")).SequenceEqual(original))throw new Exception("compatibility floor lost exact prior profile");if(marker.Version==1)throw new Exception("known older strict version-one reader would accept floor");return Task.CompletedTask;});

        await Scenario("distinct case-sensitive folder peers remain separate",()=>{var store=Owned(temp,"distinct");var start=new System.Diagnostics.ProcessStartInfo("fsutil.exe"){RedirectStandardOutput=true,RedirectStandardError=true,UseShellExecute=false};foreach(var arg in new[]{"file","setCaseSensitiveInfo",store.Root,"enable"})start.ArgumentList.Add(arg);using(var process=System.Diagnostics.Process.Start(start)!){process.WaitForExit();if(process.ExitCode!=0)throw new Exception("isolated case-sensitive directory setup failed");}Directory.CreateDirectory(store.Resolve("Notes"));Directory.CreateDirectory(store.Resolve("notes"));File.WriteAllText(store.Resolve("Notes/A.txt"),"first peer");File.WriteAllText(store.Resolve("notes/B.txt"),"second peer");store.EnsureFolders(["Notes","notes"]);if(!ExactFolder(store,"Notes")||!ExactFolder(store,"notes")||File.ReadAllText(store.Resolve("Notes/A.txt"))!="first peer"||File.ReadAllText(store.Resolve("notes/B.txt"))!="second peer")throw new Exception("distinct physical folders merged or overwritten");return Task.CompletedTask;});

        await Scenario("active capture lease excludes reentrant classification and consent",()=>{var store=Owned(temp,"lease");store.EnsureFolders(["Notes"]);var classificationRefused=false;var consentRefused=false;Hook(store,point=>{if(point!="prepared")return;var rival=new TextPackStore(store.Root,store.StateDirectory);try{_=rival.Scan();}catch(IOException){classificationRefused=true;}var row=rival.FolderRenameRecoveryList().Single();try{rival.ResolveFolderRename(row.Id,row.FromPath,row.ToPath,row.Inspection);}catch(IOException){consentRefused=true;}});store.EnsureFolders(["notes"]);if(!classificationRefused||!consentRefused||!ExactFolder(store,"notes"))throw new Exception("another store classified or acknowledged active native capture");return Task.CompletedTask;});
        foreach(var field in new[]{"Version","UnknownFuture"})await Scenario("unknown folder journal refuses without clearing original "+field,()=>{var store=Conflict(temp,"future-"+field);var path=Directory.GetFiles(Path.Combine(store.StateDirectory,"folder-case"),"*.json").Single();var value=JsonNode.Parse(File.ReadAllBytes(path))!;value[field]=2;var exact=JsonSerializer.SerializeToUtf8Bytes(value);File.WriteAllBytes(path,exact);var refused=false;try{_=store.FolderRenameRecoveryList();}catch(InvalidDataException){refused=true;}if(!refused||!File.ReadAllBytes(path).SequenceEqual(exact)||File.ReadAllText(store.Resolve("retained-original/original.txt"))!="retained original")throw new Exception("unknown journal was accepted or modified");return Task.CompletedTask;});
        await Scenario("unsafe folder descendants block metadata consent without following links",()=>{var store=Conflict(temp,"unsafe");var outside=Path.Combine(temp,"folder-case-external");Directory.CreateDirectory(outside);File.WriteAllText(Path.Combine(outside,"outside.txt"),"outside exact");Directory.CreateSymbolicLink(store.Resolve("Notes/linked"),outside);var row=store.FolderRenameRecoveryList().Single();if(row.ResolutionBlocked is null||!row.From.Present)throw new Exception("unsafe subtree was reported inspectable or absent");var refused=false;try{store.ResolveFolderRename(row.Id,row.FromPath,row.ToPath,row.Inspection);}catch(IOException){refused=true;}if(!refused||File.ReadAllText(Path.Combine(outside,"outside.txt"))!="outside exact"||!File.Exists(store.Resolve("retained-original/original.txt")))throw new Exception("unsafe metadata consent changed bytes");return Task.CompletedTask;});
        await Scenario("folder recovery refuses copied root and changed principal",()=>{var store=Conflict(temp,"scope");var row=store.FolderRenameRecoveryList().Single();var copied=new TextPackStore(Path.Combine(temp,"folder-case-copied-root"),store.StateDirectory);var copiedRefused=false;try{_=copied.FolderRenameRecoveryRead(row.Id);}catch(InvalidDataException){copiedRefused=true;}var ownerPath=Path.Combine(store.StateDirectory,AccountRootOwnership.FileName);var owner=JsonSerializer.Deserialize<AccountRootOwnership.Owner>(File.ReadAllBytes(ownerPath))!;File.WriteAllBytes(ownerPath,JsonSerializer.SerializeToUtf8Bytes(owner with{AccountId="other-account"}));var accountRefused=false;try{store.ResolveFolderRename(row.Id,row.FromPath,row.ToPath,row.Inspection);}catch(InvalidDataException){accountRefused=true;}if(!copiedRefused||!accountRefused||File.ReadAllText(store.Resolve("Notes/foreign.txt"))!="retained foreign")throw new Exception("foreign folder scope accepted");return Task.CompletedTask;});
        await Scenario("folder compatibility publication retains raced actual prior profile and refuses",()=>{var store=Owned(temp,"floor-race");store.EnsureFolders(["Notes"]);RetainedReplacementProfile.Prepare(store);var path=Path.Combine(store.StateDirectory,"retained-replacement-profile","profile.json");var original=File.ReadAllBytes(path);byte[]? foreign=null;Hook(store,point=>{if(point!="beforeFolderProfilePublication")return;var marker=JsonSerializer.Deserialize<RetainedReplacementProfile.Marker>(File.ReadAllBytes(path))!;foreign=JsonSerializer.SerializeToUtf8Bytes(marker with{PrincipalHash=new string('a',64)});File.WriteAllBytes(path,foreign);});var refused=false;try{store.EnsureFolders(["notes"]);}catch(InvalidDataException){refused=true;}var scanRefused=false;try{_=store.Scan();}catch(InvalidDataException){scanRefused=true;}if(!refused||!scanRefused||!ExactFolder(store,"Notes")||foreign is null||!File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(path)!,"profile-v1-displaced.json")).SequenceEqual(foreign)||!File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(path)!,"profile-v1.json")).SequenceEqual(original))throw new Exception("raced prior profile was lost or normal reads accepted failed publication");return Task.CompletedTask;});
        await Scenario("file command never implicitly changes an existing parent folder spelling",()=>{var store=Owned(temp,"no-implicit");var bytes=Pack();var file=store.Write("Notes/CaseProbe.textpack",bytes);var refused=false;try{store.Rename(file.Path,"notes/CaseProbe.textpack",file.Hash);}catch(IOException){refused=true;}if(!refused||!ExactFolder(store,"Notes")||!store.Read(file.Path).SequenceEqual(bytes))throw new Exception("file rename changed parent metadata implicitly");return Task.CompletedTask;});
        await Scenario("shared full-path adoption replays its existing intent after interruption",async()=>{var f=Shared(temp,"shared-intent");ExternalRename(f.Store);var stopped=false;try{SharedEditingStore.RebaseProjection(f.Store,f.File.ItemId,"notes/CaseProbe.textpack",interruptAfterIntent:true,adoptingExternalChange:true);}catch(IOException){stopped=true;}using var editing=new SharedEditingStore(new TextPackStore(f.Store.Root,f.Store.StateDirectory),Test.NewSync(f.Store,new Test.Fake()));var session=await editing.OpenAsync(f.File.ItemId,f.File.Path,f.File.Hash);if(!stopped||session.Document.Path!="notes/CaseProbe.textpack"||session.Checkpoint!.JournalGeneration!=f.Checkpoint.JournalGeneration||!f.Store.Read(session.Document.Path).SequenceEqual(f.Bytes))throw new Exception("full-path intent recovery changed retained work");});
        await Scenario("remote catalog materialization preserves active pending editor checkpoint",async()=>{var f=Shared(temp,"remote-active");var state=new SyncEngine.State();state.Items[f.File.ItemId]=new(f.File.Path,f.File.Hash,f.File.Hash);TextPackStore.AtomicWrite(Path.Combine(f.Store.StateDirectory,"sync.json"),JsonSerializer.SerializeToUtf8Bytes(state));var remote=new Test.Fake{Data=f.Bytes,Item=new(f.File.ItemId,f.File.Path,f.File.Hash),Folders=["Notes"],AuthoritativeFolders=["Notes"]};var engine=Test.NewSync(f.Store,remote);using var editing=new SharedEditingStore(f.Store,engine);var session=await editing.OpenAsync(f.File.ItemId,f.File.Path,f.File.Hash);remote.Item=remote.Item with{RelativePath="notes/CaseProbe.textpack"};remote.Folders=["notes"];remote.AuthoritativeFolders=["notes"];await engine.SyncAsync();var saved=await editing.CheckpointAsync(session.SessionToken,f.File.Hash,f.Bytes,f.Checkpoint);if(saved.Path!="notes/CaseProbe.textpack"||remote.UploadCount!=0||!f.Store.Read(saved.Path).SequenceEqual(f.Bytes))throw new Exception("remote folder catalog lost active pending projection");});

        await Scenario("pre-pin source replacement refuses without renaming the foreign directory",()=>{var store=Owned(temp,"pre-pin-race");store.EnsureFolders(["Notes"]);File.WriteAllText(store.Resolve("Notes/original.txt"),"original before pin");Hook(store,point=>{if(point!="beforeSourcePin")return;Directory.Move(store.Resolve("Notes"),store.Resolve("original-before-pin"));Directory.CreateDirectory(store.Resolve("Notes"));File.WriteAllText(store.Resolve("Notes/foreign.txt"),"foreign before pin");});var refused=false;try{store.EnsureFolders(["notes"]);}catch(IOException){refused=true;}if(!refused||!ExactFolder(store,"Notes")||ExactFolder(store,"notes")||File.ReadAllText(store.Resolve("Notes/foreign.txt"))!="foreign before pin"||File.ReadAllText(store.Resolve("original-before-pin/original.txt"))!="original before pin")throw new Exception("pre-pin foreign directory was renamed or original bytes lost");var row=store.FolderRenameRecoveryList().Single();if(row.Resolved)throw new Exception("pre-pin mismatch silently completed");return Task.CompletedTask;});
        await Scenario("nested future consent fields refuse even with matching durable byte hash",()=>{var store=Conflict(temp,"consent-future");var row=store.FolderRenameRecoveryList().Single();store.ResolveFolderRename(row.Id,row.FromPath,row.ToPath,row.Inspection);var consentPath=Path.Combine(store.StateDirectory,"folder-case","consents",row.Id+".json");var consent=JsonNode.Parse(File.ReadAllBytes(consentPath))!;consent["From"]!["Future"]=1;var bytes=JsonSerializer.SerializeToUtf8Bytes(consent);File.WriteAllBytes(consentPath,bytes);var journalPath=Path.Combine(store.StateDirectory,"folder-case",row.Id+".json");var journal=JsonNode.Parse(File.ReadAllBytes(journalPath))!;journal["ConsentHash"]=TextPackStore.Hash(bytes);File.WriteAllBytes(journalPath,JsonSerializer.SerializeToUtf8Bytes(journal));var refused=false;try{_=store.FolderRenameRecoveryRead(row.Id);}catch(InvalidDataException){refused=true;}if(!refused||!File.ReadAllBytes(consentPath).SequenceEqual(bytes))throw new Exception("future nested consent accepted or rewritten");return Task.CompletedTask;});
        await Scenario("inventory checks folder history once and refuses a change during the scan",()=>{
            var store=Owned(temp,"scan-scope");store.EnsureFolders(["Notes"]);store.EnsureFolders(["notes"]);
            for(var i=0;i<300;i++){using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true))using(var writer=new StreamWriter(zip.CreateEntry("text.md").Open()))writer.Write("---\ntextTextId: scope-"+i+"\n---\n");File.WriteAllBytes(store.Resolve("notes/item-"+i+".textpack"),output.ToArray());}
            var hook=typeof(TextPackStore).GetProperty("InventoryObservationForTesting",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!;
            var checks=0;hook.SetValue(store,(Action<string>)(phase=>{if(phase=="folderCaseChecked")checks++;}));
            var timing=System.Diagnostics.Stopwatch.StartNew();var files=store.Scan();Console.WriteLine("FOLDER_CASE_SCOPE_300_MS "+timing.ElapsedMilliseconds);
            if(files.Count!=300||checks!=1)throw new Exception("scan did not share one folder-case check across all files: files="+files.Count+" checks="+checks);
            var journal=Directory.GetFiles(Path.Combine(store.StateDirectory,"folder-case"),"*.json").Single();var original=File.ReadAllBytes(journal);
            hook.SetValue(store,(Action<string>)(phase=>{if(phase=="scanned"){var value=JsonNode.Parse(original)!;value["State"]="conflict";File.WriteAllBytes(journal,JsonSerializer.SerializeToUtf8Bytes(value));}}));
            var refused=false;try{_=store.Scan();}catch(InvalidDataException){refused=true;}
            hook.SetValue(store,null);
            var later=false;try{_=store.Scan();}catch(IOException){later=true;}
            File.WriteAllBytes(journal,original);
            if(!refused||!later||store.Scan().Count!=300)throw new Exception("folder history change during inventory was accepted");
            return Task.CompletedTask;});
        check(failures.Count==0,"all folder case scenarios pass: "+string.Join("; ",failures));
    }
}
